/*
 	Unreal #genuary24 Impossible objects (undecided geometry).
	https://openprocessing.org/sketch/2154554
	#genuary24 #genuary #creativecoding #generativeart #p5js
	https://genuary.art/prompts#jan24
*/

const S = 600;
const numModes = 3; // 0 = mask, 1..2 = different objects
const masks = ["purple", "orange"];
let buffers, replShader, objs, obj1, obj2;

let drawMode = 0;

function setup() {
	// createCanvas(windowWidth, windowHeight, WEBGL);
	createCanvas(S, S, WEBGL);
	background("black")
	describe("rotating 3d-cube with inner box or torus, depending on rotation angle. postprocessing dithering and tinted in cyan.")
	pixelDensity(0.5);
	imageMode(CENTER);

	buffers = [];
	for (let i = 0; i < numModes; i++) {
		// createGraphics(S, S, WEBGL) // createFramebuffer({ format: FLOAT });
		buffers[i] = createFramebuffer({format: FLOAT }); 
	}

	objs = [];
	for (let i = 0; i < 50; i++) {
		const a = random(TWO_PI);
		const r = random(2*S, 5 * S)
		const d = random(S * 0.25, S * 1.5)
		const c = color(random(128, 333), random(255), random(128), 128)
		const p = createVector(cos(a)*r, sin(a)*r, i)
		objs.push({p, d, c})
	}

	replShader = createFilterShader(fragMask);
	replDither = createFilterShader(fragDither);

	// define objects for the scene;
	obj1 = ~~random(4) + 1;
	obj2 = obj1;
	while (obj2 === obj1) {
		obj2 = ~~random(4) + 1;
	}
}

function mousePressed() {
	if (mouseButton === LEFT) {
		drawMode = (drawMode + 1) % numModes;
	}
}

function draw() {
	// background("black")

	for (let i = 0; i < numModes; i++) {
		makeScenes(buffers[i], i);	
	}
	image(buffers[0], 0, 0); // image(buffers[drawMode], 0, 0);

	// https://p5js.org/reference/#/p5.Shader/setUniform
	replShader.setUniform('darkness', 1); // map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0.1, 2)

	replShader.setUniform('tex1', buffers[1]);
	const msk1 = color(masks[0]);
	replShader.setUniform('msk1', [red(window.color(msk1))/255, green(window.color(msk1))/255, blue(window.color(msk1))/255]); //  becomes uniform vec3 x with the value vec3(0.0, 0.5, 1.0)
	replShader.setUniform('dst1', 0.5);

  replShader.setUniform('tex2', buffers[2]);
	const msk2 = color(masks[1]);
	replShader.setUniform('msk2', [red(window.color(msk2))/255, green(window.color(msk2))/255, blue(window.color(msk2))/255]); //  becomes uniform vec3 x with the value vec3(0.0, 0.5, 1.0)
	replShader.setUniform('dst2', 0.5);

	// tint added to dithering shader
	replShader.setUniform('tint', [222.0, 0.7, 0.7]); // not working, hard coded in shader

	filter(replShader); // replace masks with textures tex1, tex2
	if (!(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton===LEFT)) filter(replDither); // dither, disable when LMB
}

// generate scene with alternating objects under the table
function makeScenes(fb, drawMode) {
	fb.begin();
	background("lightblue");

	rotateX(1.25)
	translate(0, 0, -100)
	// translate(0, 200, 100 + sin(frameCount * 0.05) * 20)
	rotateZ(frameCount * 0.02);

	lights();
	// ambientLight(255);
	directionalLight(250, 250, 250, -1, -1, -1);

	noStroke();
	fill("lightgreen")
	// plane(10000, 10000)
	circle(0, 0, 10000)

	fill("darkblue")
	push()
	translate(0, 0, 1);
	// plane(600, 600)
	circle(0, 0, 600)
	for (let o of objs) {
		push()
		translate(o.p)
		fill(o.c)
		circle(0, 0, o.d)
		pop()
	}
	pop()

	// ^^ hardcoded sizes
	const d1 = 200;
	const d2 = 180;


	if (true) {
		const dd = d1 - d2;
		push()
		translate(0, 0, (d2) * 0.5);

		// outer house: roof + 4 corners
		for (let i = 0; i < 4; i++) {
			push()
			translate(0, d1 * 0.5, 0);
			fill(color(masks[i%masks.length])); // color masks
			if (drawMode === 0) box(d2, dd, d2)
			fill("rgb(80,80,80)");
			translate((d1) * 0.5, 0, 0);
			box(dd, dd, d2)
			pop()
			rotateZ(PI * 0.5)
		}

		if (drawMode > 0) {
			let obj = drawMode === 1 ? obj1 : obj2;
			push()
			fill(masks[drawMode - 1])
			translate(0, 0, - d2 * 0.1)

			if (obj === 1) {
				box(d2 * 0.55);
			}

			if (obj === 2) {
				rotateX(HALF_PI * 0.75);
				rotateY(QUARTER_PI * 0.25);
				torus(d2 * 0.3, d2 * 0.15);
			}

			if (obj === 3) sphere(d2 * 0.4);

			if (obj === 4) {
				translate( 0, 0, -d2 * 0.2)
				// rotateX(-1.25 + HALF_PI*0.5)
				rotateX(HALF_PI)
				translate(0, d2 * 0.2, 0)
				// translate(- d2 * 0.8, 0, -d2 * 0.8)
				cone(d2 * 0.4, d2 * 0.8, 5, 3);
			}

			pop();
		}

		translate(0, 0, d2 * 0.5 - dd * 0.5 + 1);
		fill("darkgray");
		box(d1 + dd + dd * 0.5, d1 + dd + dd * 0.5, dd)

		pop();
		fb.end()
	}
}
